import { apiFetch } from "./client";

// ── Types ──

export interface Author {
  name: string;
  id?: string | null;
  affiliations?: string[];
}

export interface Paper {
  id: string;
  source: string;
  title: string;
  abstract: string | null;
  authors: Author[];
  year: number | null;
  venue: string | null;
  citation_count: number | null;
  url: string | null;
  doi: string | null;
  arxiv_id: string | null;
  keywords: string[];
}

export interface SearchResponse {
  papers: Paper[];
}

export interface IngestResponse {
  status: string;
  id: string;
}

// ── API Calls ──

/** Search academic literature across multiple sources. */
export function searchLiterature(
  query: string,
  maxResults: number = 10,
): Promise<SearchResponse> {
  return apiFetch<SearchResponse>(
    `/literature/search?q=${encodeURIComponent(query)}&max_results=${maxResults}`,
  );
}

/** Ingest a paper into the knowledge base. */
export function ingestPaper(paper: Paper): Promise<IngestResponse> {
  return apiFetch<IngestResponse>("/literature/ingest", {
    method: "POST",
    body: JSON.stringify(paper),
  });
}

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ExternalLink, BookOpen } from "lucide-react";
import type { Paper } from "@/api/literature";

export interface PaperCardProps {
  paper: Paper;
  onIngest: (paper: Paper) => void;
}

function sourceColor(source: string): string {
  switch (source) {
    case "semantic_scholar":
      return "bg-blue-100 text-blue-800";
    case "arxiv":
      return "bg-red-100 text-red-800";
    case "openalex":
      return "bg-green-100 text-green-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
}

export function PaperCard({ paper, onIngest }: PaperCardProps) {
  const [confirming, setConfirming] = useState(false);

  function handleIngestClick() {
    if (!confirming) {
      setConfirming(true);
      return;
    }
    onIngest(paper);
    setConfirming(false);
  }

  const authorNames = paper.authors.map((a) => a.name).join(", ");
  const truncatedAbstract =
    paper.abstract && paper.abstract.length > 250
      ? paper.abstract.slice(0, 250) + "…"
      : paper.abstract;

  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-start justify-between gap-2">
          <h3 className="font-semibold text-sm leading-tight" data-testid="paper-title">
            {paper.title}
          </h3>
          {paper.url && (
            <a
              href={paper.url}
              target="_blank"
              rel="noopener noreferrer"
              className="shrink-0 text-muted-foreground hover:text-foreground"
            >
              <ExternalLink className="h-4 w-4" />
            </a>
          )}
        </div>

        {authorNames && (
          <p className="text-xs text-muted-foreground mt-1" data-testid="paper-authors">
            {authorNames}
          </p>
        )}

        {truncatedAbstract && (
          <p className="text-xs text-muted-foreground mt-2 line-clamp-3">
            {truncatedAbstract}
          </p>
        )}

        <div className="flex items-center flex-wrap gap-2 mt-3">
          <Badge variant="outline" className={`text-xs ${sourceColor(paper.source)}`}>
            {paper.source}
          </Badge>
          {paper.year && (
            <Badge variant="outline" className="text-xs" data-testid="paper-year">
              {paper.year}
            </Badge>
          )}
          {paper.citation_count != null && (
            <span className="text-xs text-muted-foreground">
              {paper.citation_count.toLocaleString()} citations
            </span>
          )}
          {paper.doi && (
            <span className="text-xs text-muted-foreground truncate max-w-[180px]">
              DOI: {paper.doi}
            </span>
          )}
        </div>

        <div className="mt-3 flex justify-end">
          <Button
            size="sm"
            variant={confirming ? "destructive" : "outline"}
            onClick={handleIngestClick}
            data-testid="ingest-button"
          >
            <BookOpen className="h-3 w-3 mr-1" />
            {confirming ? "Confirm Ingest" : "Ingest"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { searchLiterature, ingestPaper } from "@/api/literature";
import { PaperCard } from "@/components/literature/paper-card";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Search, BookOpen, AlertCircle, Inbox } from "lucide-react";
import type { Paper } from "@/api/literature";

export default function LiteraturePage() {
  const [query, setQuery] = useState("");
  const [submittedQuery, setSubmittedQuery] = useState<string | null>(null);

  const queryClient = useQueryClient();

  const {
    data: searchData,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["literature-search", submittedQuery],
    queryFn: () => searchLiterature(submittedQuery!),
    enabled: !!submittedQuery,
  });

  const ingestMutation = useMutation({
    mutationFn: (paper: Paper) => ingestPaper(paper),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["literature-search"] });
    },
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;
    setSubmittedQuery(query.trim());
  }

  function handleIngest(paper: Paper) {
    ingestMutation.mutate(paper);
  }

  const papers = searchData?.papers ?? [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Literature Search</h1>
        <p className="text-muted-foreground">
          Search across Semantic Scholar, arXiv, and OpenAlex for academic papers.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Search papers by topic, author, or keyword..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="pl-9"
          data-testid="literature-search-input"
        />
      </form>

      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-32 w-full" />
          ))}
        </div>
      ) : isError ? (
        <div className="text-center py-12 text-destructive">
          <AlertCircle className="h-8 w-8 mx-auto mb-2 opacity-70" />
          <p data-testid="search-error">Search failed. Please try again.</p>
        </div>
      ) : submittedQuery && papers.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          <Inbox className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p data-testid="no-results">No papers found for &quot;{submittedQuery}&quot;.</p>
        </div>
      ) : papers.length > 0 ? (
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            <BookOpen className="h-4 w-4 inline mr-1" />
            {papers.length} paper{papers.length !== 1 ? "s" : ""} for &quot;{submittedQuery}&quot;
          </p>
          {papers.map((paper) => (
            <PaperCard key={paper.id} paper={paper} onIngest={handleIngest} />
          ))}
        </div>
      ) : null}
    </div>
  );
}

